        readonly ToolStrip tools=new ToolStrip(),modes=new ToolStrip();readonly Dictionary<string,ToolStripButton> modeButtons=new Dictionary<string,ToolStripButton>();ToolStripButton drawButton,viewButton;ScenePick lastPick;
        readonly string root=AppDomain.CurrentDomain.BaseDirectory;readonly string patchRoot=GameIntegration.PatchDirectory;
        public EditorForm(string romPath){
            Text="DoomSNESed - Reality Engine editor";Width=1480;Height=940;MinimumSize=new Size(1120,760);StartPosition=FormStartPosition.CenterScreen;Font=new Font("Segoe UI",10);BackColor=Theme.Background;ForeColor=Theme.Text;
            Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);banner.BrandIcon=Icon;
            var menu=MakeMenu();MainMenuStrip=menu;tools.Renderer=modes.Renderer=new EditorMenuRenderer();tools.GripStyle=modes.GripStyle=ToolStripGripStyle.Hidden;tools.BackColor=modes.BackColor=Theme.Panel;tools.ForeColor=modes.ForeColor=Theme.Text;tools.Padding=modes.Padding=new Padding(10,4,10,3);
            Tool(tools,"Open ROM",OpenRomDialog);Tool(tools,"Save project",delegate{SaveProject(false);});Tool(tools,"New map",NewMap);tools.Items.Add(new ToolStripSeparator());
            Tool(tools,"Check map  [F5]",CheckMap);var apply=Tool(tools,"Apply to game  [F6]",Apply);apply.Font=new Font(Font,FontStyle.Bold);Tool(tools,"Original levels",ClearPatch);
            foreach(var pair in new[]{new[]{"Objects","1  Things"},new[]{"Vertices","2  Vertices"},new[]{"Walls","3  Linedefs"},new[]{"Sectors","4  Sectors"},new[]{"Surfaces","5  Surfaces"}}){string id=pair[0];modeButtons[id]=Tool(modes,pair[1],delegate{SelectMode(id);});}
            modes.Items.Add(new ToolStripSeparator());drawButton=Tool(modes,"Draw  [D]",StartDraw);viewButton=Tool(modes,"3D view  [F3]",Toggle3D);Tool(modes,"Fit",canvas.Fit);
            var preset=new ToolStripDropDownButton("Sector preset"){ForeColor=Theme.Text};foreach(SectorMotion motion in Enum.GetValues(typeof(SectorMotion))){SectorMotion choice=motion;var item=new ToolStripMenuItem(motion.ToString());item.Click+=delegate{Guard(delegate{Preset(choice);});};preset.DropDownItems.Add(item);}modes.Items.Add(preset);
            var grid=new ToolStripDropDownButton("Grid: 16"){ForeColor=Theme.Text};foreach(int size in new[]{4,8,16,32,64,128}){int value=size;var item=new ToolStripMenuItem(size.ToString());item.Click+=delegate{canvas.Grid=value;grid.Text="Grid: "+value;canvas.Invalidate();};grid.DropDownItems.Add(item);}modes.Items.Add(grid);
            var outer=new SplitContainer{Width=1450,Dock=DockStyle.Fill,SplitterDistance=190,FixedPanel=FixedPanel.Panel1,BackColor=Theme.Border,SplitterWidth=3};
            var inner=new SplitContainer{Width=1250,Dock=DockStyle.Fill,SplitterDistance=910,FixedPanel=FixedPanel.Panel2,BackColor=Theme.Border,SplitterWidth=3};outer.Panel2.Controls.Add(inner);
            maps.Dock=DockStyle.Fill;maps.BackColor=Theme.Panel;maps.ForeColor=Theme.Text;maps.BorderStyle=BorderStyle.None;maps.IntegralHeight=false;maps.DrawMode=DrawMode.OwnerDrawFixed;maps.ItemHeight=30;
            maps.DrawItem+=delegate(object sender,DrawItemEventArgs e){if(e.Index<0)return;Map m=(Map)maps.Items[e.Index];using(var fill=new SolidBrush((e.State&DrawItemState.Selected)!=0?Color.FromArgb(44,79,48):Theme.Panel))e.Graphics.FillRectangle(fill,e.Bounds);TextRenderer.DrawText(e.Graphics,m.Name+(m.EditGeometry||m.NewRoom?"    custom":""),Font,e.Bounds,Theme.Text,TextFormatFlags.Left|TextFormatFlags.VerticalCenter);};
            var levelTitle=new Label{Text="  LEVELS",Dock=DockStyle.Top,Height=38,ForeColor=Theme.Accent,TextAlign=ContentAlignment.MiddleLeft,BackColor=Theme.Panel};
            var search=new TextBox{Dock=DockStyle.Top,BackColor=Theme.Raised,ForeColor=Theme.Text,BorderStyle=BorderStyle.FixedSingle};search.TextChanged+=delegate{if(rom!=null)RefreshMaps(map==null?0:map.Slot,search.Text);};
            var leftBottom=new Label{Dock=DockStyle.Bottom,Height=90,Padding=new Padding(12),BackColor=Theme.Panel,ForeColor=Theme.Muted,Text="22 native map slots\nNew maps replace a slot.\nYour ROM stays unchanged."};outer.Panel1.Controls.Add(maps);outer.Panel1.Controls.Add(search);outer.Panel1.Controls.Add(levelTitle);outer.Panel1.Controls.Add(leftBottom);
            viewport.Dock=DockStyle.Fill;viewport.Controls.Add(scene);viewport.Controls.Add(canvas);scene.Visible=false;inner.Panel1.Controls.Add(viewport);
            selection.Dock=DockStyle.Top;selection.Height=38;selection.BackColor=Theme.Raised;selection.ForeColor=Theme.Accent;selection.Padding=new Padding(10);selection.Text="THINGS";
            items.Dock=DockStyle.Top;items.Height=155;items.BackColor=Theme.Panel;items.ForeColor=Theme.Text;items.BorderStyle=BorderStyle.None;items.IntegralHeight=false;items.SelectionMode=SelectionMode.MultiExtended;
            properties.Dock=DockStyle.Fill;properties.ToolbarVisible=false;properties.PropertySort=PropertySort.Categorized;properties.ViewBackColor=Theme.Panel;properties.ViewForeColor=Theme.Text;properties.HelpBackColor=Theme.Background;properties.HelpForeColor=Theme.Muted;properties.CategoryForeColor=Theme.Accent;properties.LineColor=Theme.Border;
            preview.Height=145;preview.BackColor=Theme.Background;guide.Dock=DockStyle.Bottom;guide.Height=58;guide.Padding=new Padding(9);guide.ForeColor=Theme.Muted;guide.BackColor=Theme.Panel;guide.Font=new Font("Segoe UI",9);
            var assets=Theme.Button("Browse surface assets...");assets.Dock=DockStyle.Bottom;assets.Height=35;assets.Click+=delegate{Guard(ChooseAsset);};
            inner.Panel2.BackColor=Theme.Panel;inner.Panel2.Controls.Add(properties);inner.Panel2.Controls.Add(guide);inner.Panel2.Controls.Add(preview);inner.Panel2.Controls.Add(assets);inner.Panel2.Controls.Add(items);inner.Panel2.Controls.Add(selection);
            var strip=new StatusStrip{BackColor=Theme.Panel,ForeColor=Theme.Muted};status.Spring=true;status.TextAlign=ContentAlignment.MiddleLeft;strip.Items.Add(status);strip.Items.Add(position);
            var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=6,Padding=Padding.Empty,Margin=Padding.Empty};layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));foreach(float h in new[]{25f,70f,43f,39f})layout.RowStyles.Add(new RowStyle(SizeType.Absolute,h));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,23));
            Control[] rows={menu,banner,tools,modes,outer,strip};for(int i=0;i<rows.Length;i++){rows[i].Dock=DockStyle.Fill;rows[i].Margin=Padding.Empty;layout.Controls.Add(rows[i],0,i);}Controls.Add(layout);
            maps.SelectedIndexChanged+=delegate{if(!refreshing&&maps.SelectedItem!=null)SelectMap((Map)maps.SelectedItem);};items.SelectedIndexChanged+=delegate{if(!refreshing){canvas.Selection.Clear();foreach(int i in items.SelectedIndices)canvas.Selection.Add(i);SelectItem(items.SelectedIndex);SelectMultiple();}};
            properties.PropertyValueChanged+=delegate{Commit();preview.Invalidate();canvas.Invalidate();scene.Invalidate();};properties.SelectedGridItemChanged+=delegate{PreviewProperty();};
            canvas.OnSelect=delegate(int index){refreshing=true;items.ClearSelected();foreach(int i in canvas.Selection)if(i>=0&&i<items.Items.Count)items.SetSelected(i,true);refreshing=false;if(index>=0)SelectItem(index);SelectMultiple();};canvas.OnContext=delegate{Guard(EditSelectionDialog);};
            canvas.OnEdit=delegate{int selected=canvas.Selected;Commit();RefreshItems(selected);};canvas.OnAdd=AddObject;canvas.OnGeometryEdit=EnableGeometry;canvas.OnFinish=FinishOutline;canvas.OnHint=delegate(string text){position.Text=text;};canvas.OnToolEnd=UpdateButtons;
            scene.OnPick=Pick3D;scene.OnExit=Toggle3D;scene.OnHeight=delegate(int sector,bool ceiling,int amount){Guard(delegate{Edit(delegate{EnableCurrent();Sector s=map.Sectors[sector];if(ceiling)s.Ceiling=Math.Max(s.Floor,Math.Min(4096,s.Ceiling+amount));else s.Floor=Math.Min(s.Ceiling,Math.Max(-4096,s.Floor+amount));});});};
            Shown+=delegate{if(!string.IsNullOrEmpty(romPath))Guard(delegate{LoadRom(romPath);});else Status("Open your Doom USA ROM to begin. Use New map for an empty canvas or select an existing level.");};
            FormClosing+=delegate(object sender,FormClosingEventArgs e){if(!CanDiscard())e.Cancel=true;};UpdateButtons();
        }
        MenuStrip MakeMenu(){var menu=new MenuStrip{Renderer=new EditorMenuRenderer(),BackColor=Theme.Panel,ForeColor=Theme.Text};var file=new ToolStripMenuItem("File");menu.Items.Add(file);
            Add(file,"Open ROM...",OpenRomDialog,Keys.Control|Keys.O);Add(file,"Open project...",OpenProject,Keys.Control|Keys.Shift|Keys.O);Add(file,"Save project",delegate{SaveProject(false);},Keys.Control|Keys.S);Add(file,"Save project as...",delegate{SaveProject(true);},Keys.Control|Keys.Shift|Keys.S);Add(file,"New map...",NewMap,Keys.Control|Keys.N);file.DropDownItems.Add(new ToolStripSeparator());Add(file,"Export patched ROM copy...",ExportRom,Keys.None);Add(file,"Export level patch...",ExportPatch,Keys.None);Add(file,"Exit",Close,Keys.Alt|Keys.F4);
            var edit=new ToolStripMenuItem("Edit");menu.Items.Add(edit);Add(edit,"Undo",delegate{History(false);},Keys.Control|Keys.Z);Add(edit,"Redo",delegate{History(true);},Keys.Control|Keys.Y);Add(edit,"Delete selection",DeleteSelection,Keys.Delete);Add(edit,"Flip selected two-sided linedef",FlipLine,Keys.Control|Keys.F);Add(edit,"Restore selected map from ROM",RestoreMap,Keys.None);
            var view=new ToolStripMenuItem("View");menu.Items.Add(view);Add(view,"2D / 3D view",Toggle3D,Keys.F3);Add(view,"Fit map",canvas.Fit,Keys.Control|Keys.Home);Add(view,"Reset 3D camera to player start",scene.ResetCamera,Keys.None);var openDoors=new ToolStripMenuItem("Preview doors open"){CheckOnClick=true};openDoors.CheckedChanged+=delegate{scene.OpenDoors=openDoors.Checked;scene.Invalidate();};view.DropDownItems.Add(openDoors);
            var build=new ToolStripMenuItem("Build");menu.Items.Add(build);Add(build,"Check native map",CheckMap,Keys.F5);Add(build,"Apply for next game launch",Apply,Keys.F6);Add(build,"Use original levels next launch",ClearPatch,Keys.None);
            var help=new ToolStripMenuItem("Help");menu.Items.Add(help);Add(help,"Quick guide",Help,Keys.F1);return menu;
        }
        void Add(ToolStripMenuItem parent,string text,Action action,Keys shortcut){var item=new ToolStripMenuItem(text){ShortcutKeys=shortcut};item.Click+=delegate{Guard(action);};parent.DropDownItems.Add(item);}
        ToolStripButton Tool(ToolStrip toolbar,string text,Action action){var button=new ToolStripButton(text){DisplayStyle=ToolStripItemDisplayStyle.Text,ForeColor=Theme.Text,Padding=new Padding(6,2,6,2)};button.Click+=delegate{Guard(action);};toolbar.Items.Add(button);return button;}
        void Guard(Action action){try{action();}catch(Exception e){if(Environment.GetCommandLineArgs().Contains("--ui-smoke-test"))throw;MessageBox.Show(this,e.Message,"DoomSNESed",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
        void Status(string message){status.Text=message;}
        void NeedRom(){Bin.Require(rom!=null,"Open your Doom SNES ROM first.");}
        bool CanDiscard(){return !dirty||MessageBox.Show(this,"Discard unsaved changes? Applied levels have their own saved copy.","DoomSNESed",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes;}
        void OpenRomDialog(){if(!CanDiscard())return;using(var dialog=new OpenFileDialog{Title="Open Doom (USA) SNES ROM",Filter="SNES ROM|*.sfc;*.smc"})if(dialog.ShowDialog(this)==DialogResult.OK)LoadRom(dialog.FileName);}
        void LoadRom(string path){var loaded=new Rom(path,Path.Combine(root,"editor-data"));string active=Path.Combine(patchRoot,"active.sned");bool restored=File.Exists(Path.Combine(patchRoot,"active.dse"))&&File.Exists(active);if(restored)loaded.LoadProject(active);rom=loaded;Context.Rom=rom;canvas.Rom=scene.Rom=rom;projectPath=null;dirty=false;undo.Clear();redo.Clear();RefreshMaps(rom.Project.CampaignSlots==null?0:rom.Project.CampaignSlots[0],"");lastSnapshot=Snapshot();Status(restored?"Your applied project has been restored.":"ROM verified. Choose New map to draw, or edit a level from the list.");}
        string Snapshot(){return ProjectJson.Create().Serialize(map);}
        void RestoreSnapshot(string json,int slot){Map restored=ProjectJson.Create().Deserialize<Map>(json);int index=rom.Project.Maps.FindIndex(m=>m.Slot==restored.Slot);rom.Project.Maps[index]=restored;RefreshMaps(restored.Slot,"");}
        void Edit(Action action){NeedRom();string before=Snapshot();int slot=map.Slot;try{int[] selected=canvas.Selection.ToArray();action();Commit();RefreshItems(items.SelectedIndex);if(mode=="Walls"||mode=="Sectors"){refreshing=true;items.ClearSelected();canvas.Selection.Clear();foreach(int i in selected)if(i>=0&&i<items.Items.Count){canvas.Selection.Add(i);items.SetSelected(i,true);}refreshing=false;SelectMultiple();}}catch{RestoreSnapshot(before,slot);throw;}}
        void Commit(){if(rom==null)return;string now=Snapshot();if(now!=lastSnapshot){undo.Push(lastSnapshot);redo.Clear();lastSnapshot=now;dirty=true;}Text="DoomSNESed - "+map.Name+(dirty?" *":"");canvas.Invalidate();scene.Invalidate();maps.Invalidate();UpdateBanner();}
        void History(bool forward){NeedRom();Stack<string> from=forward?redo:undo,to=forward?undo:redo;if(from.Count==0)return;string target=from.Pop();Map targetMap=ProjectJson.Create().Deserialize<Map>(target);to.Push(ProjectJson.Create().Serialize(rom.Project.Maps.First(m=>m.Slot==targetMap.Slot)));RestoreSnapshot(target,targetMap.Slot);lastSnapshot=target;dirty=true;UpdateBanner();}
        void RefreshMaps(int slot,string filter){refreshing=true;maps.Items.Clear();foreach(Map m in rom.Project.Maps.Where(m=>m.Name.IndexOf(filter,StringComparison.OrdinalIgnoreCase)>=0))maps.Items.Add(m);refreshing=false;Map selected=maps.Items.Cast<Map>().FirstOrDefault(m=>m.Slot==slot)??maps.Items.Cast<Map>().FirstOrDefault();if(selected!=null)maps.SelectedItem=selected;}
        void SelectMap(Map selected){bool changed=map!=selected;map=selected;canvas.Map=scene.Map=map;canvas.Selected=-1;canvas.Selection.Clear();canvas.CancelOutline();lastSnapshot=Snapshot();Text="DoomSNESed - "+map.Name+(dirty?" *":"");RefreshItems(0);if(changed){canvas.Fit();scene.ResetCamera();}UpdateBanner();}
        void UpdateBanner(){if(map==null)return;banner.Detail=map.Name+"   "+map.Sectors.Count+" sectors   "+map.Walls.Count+" lines   "+map.Things.Count+" things";banner.Invalidate();}
        void SelectMode(string value){mode=value;canvas.Selection.Clear();canvas.Mode=value;canvas.Drawing=false;canvas.CancelOutline();RefreshItems(0);UpdateButtons();canvas.Invalidate();if(!scene.Visible)canvas.Focus();}
        void UpdateButtons(){foreach(var pair in modeButtons){pair.Value.Checked=pair.Key==mode;pair.Value.BackColor=pair.Key==mode?Theme.Raised:Theme.Panel;}if(drawButton!=null){drawButton.Checked=canvas.Drawing;drawButton.BackColor=canvas.Drawing?Theme.Raised:Theme.Panel;}if(viewButton!=null)viewButton.Text=scene.Visible?"2D view  [F3]":"3D view  [F3]";}
        void RefreshItems(int selected){refreshing=true;items.BeginUpdate();items.Items.Clear();properties.SelectedObject=null;preview.Clear();canvas.Selected=-1;canvas.Mode=mode;selection.Text=mode=="Objects"?"THINGS":mode=="Walls"?"LINEDEFS":mode.ToUpperInvariant();
            if(map!=null){if(mode=="Objects")for(int i=0;i<map.Things.Count;i++){Thing t=map.Things[i];items.Items.Add(i+"  "+rom.ObjectName(t.Type)+"   ("+t.X+", "+t.Y+")");}
                else if(mode=="Vertices")for(int i=0;i<map.Vertices.Count;i++)items.Items.Add(i+"   X "+map.Vertices[i].X+"   Y "+map.Vertices[i].Y);
                else if(mode=="Sectors")for(int i=0;i<map.Sectors.Count;i++){Sector s=map.Sectors[i];items.Items.Add("Sector "+i+"   "+s.Floor+" / "+s.Ceiling+(s.Motion==SectorMotion.None?"":"   "+s.Motion));}
                else if(mode=="Walls")for(int i=0;i<map.Walls.Count;i++)items.Items.Add("Line "+i+"   "+(map.Walls[i].Type==0?"Normal":((NativeAction)map.Walls[i].Type).ToString())+"   tag "+map.Walls[i].Tag);
                else for(int i=0;i<map.Faces.Count;i++)items.Items.Add("Surface "+i+"   sector "+map.Faces[i].Near+(map.Faces[i].Solid?"":" / "+map.Faces[i].Far));
            }items.EndUpdate();refreshing=false;if(items.Items.Count>0)items.SelectedIndex=Math.Max(0,Math.Min(selected,items.Items.Count-1));canvas.Invalidate();scene.Invalidate();
        }
        void SelectItem(int index){if(map==null||index<0)return;canvas.Selected=index;selection.Text=(mode=="Objects"?"THING ":mode=="Walls"?"LINEDEF ":mode=="Vertices"?"VERTEX ":mode=="Sectors"?"SECTOR ":"SURFACE ")+index;
            if(mode=="Objects"){Thing t=map.Things[index];properties.SelectedObject=t.Type<6?(object)new FacingThingProperties(t):new ThingProperties(t);guide.Text="Double-click the map to place a thing. Change its type and skill settings here.";}
            else if(mode=="Vertices"){properties.SelectedObject=new VertexProperties(map,index);guide.Text="Drag vertices on the grid, or enter exact coordinates. Geometry is rebuilt when you check/apply.";}
            else if(mode=="Sectors"){properties.SelectedObject=new EditableSectorProperties(map,index);preview.ShowFlat(rom,map.Sectors[index].FloorTexture);guide.Text="Floor type controls damage, secrets and lighting. Motion presets add linked native actions.";}
            else if(mode=="Walls"){properties.SelectedObject=new LineProperties(map,index);Face f=GeometryTools.Front(map,map.Walls[index]);if(f!=null)preview.ShowWall(rom,f.Upper);guide.Text="Use actions need the Use/Open button. Walk actions trigger when crossed. Match target tags to sectors.";}
            else{Face f=map.Faces[index];properties.SelectedObject=new FaceProperties(f);preview.ShowWall(rom,f.Upper);guide.Text="Choose Browse surface assets for visual texture selection. SNES floors use palette colours.";}canvas.Invalidate();
        }
        object PropertyObject(int i){return mode=="Walls"?(object)new LineProperties(map,i):new EditableSectorProperties(map,i);}
        void SelectMultiple(){if(mode!="Walls"&&mode!="Sectors")return;int[] ids=canvas.Selection.OrderBy(i=>i).ToArray();properties.SelectedObjects=ids.Select(PropertyObject).ToArray();if(ids.Length>1)selection.Text=ids.Length+" "+(mode=="Walls"?"LINEDEFS":"SECTORS")+" SELECTED";}
        void EditSelectionDialog(){NeedRom();if(mode!="Walls"&&mode!="Sectors")return;int[] ids=canvas.Selection.OrderBy(i=>i).ToArray();if(ids.Length==0)return;string before=Snapshot();int slot=map.Slot;using(var dialog=new SelectionDialog(rom,ids.Select(PropertyObject).ToArray(),mode=="Walls")){if(dialog.ShowDialog(this)==DialogResult.OK){Commit();RefreshItems(ids[0]);}else RestoreSnapshot(before,slot);}}
        void PreviewProperty(){if(rom==null||properties.SelectedGridItem==null||properties.SelectedGridItem.PropertyDescriptor==null)return;object value=properties.SelectedGridItem.Value;if(!(value is int))return;string name=properties.SelectedGridItem.PropertyDescriptor.Name;if(new[]{"WallTexture","UpperOrMiddle","Lower","FrontTexture","FrontLower","BackTexture","BackLower"}.Contains(name))preview.ShowWall(rom,(int)value);else if(name=="FloorTexture"||name=="CeilingTexture")preview.ShowFlat(rom,(int)value);}
        void EnableCurrent(){GeometryTools.Enable(map,map.RoomTexture==0?rom.MakeRoom(map.Slot,1024,1024).RoomTexture:map.RoomTexture);}
        bool EnableGeometry(){bool ok=false;Guard(delegate{EnableCurrent();Commit();ok=true;});return ok;}
        void StartDraw(){NeedRom();if(scene.Visible)Toggle3D();canvas.Drawing=true;canvas.CancelOutline();canvas.Focus();UpdateButtons();Status("Draw a closed outline beside existing sectors. For a dividing linedef, choose two boundary points and press Enter.");}
        bool FinishOutline(List<Point> points){bool ok=false;Guard(delegate{Edit(delegate{EnableCurrent();if(points.Count==2)GeometryTools.Divide(map,points[0],points[1],map.RoomTexture);else GeometryTools.AddPolygon(map,points,map.RoomTexture);if(!map.Things.Any(t=>t.Type==0)){Point spot=PlayerSpot();map.Things.Add(new Thing{Type=0,Flags=0xef,X=spot.X,Y=spot.Y});}ok=true;});if(ok){mode="Sectors";RefreshItems(map.Sectors.Count-1);Status("Sector created. Shared edges become portals automatically. Set heights, floor type or a motion preset on the right.");UpdateButtons();}});return ok;}
        Point PlayerSpot(){for(int s=0;s<map.Sectors.Count;s++){Point center=GeometryTools.Center(map,s);if(ClearSpot(center,s))return center;var points=GeometryTools.Boundary(map,s).SelectMany(i=>new[]{map.Vertices[map.Walls[i].Start],map.Vertices[map.Walls[i].End]}).ToArray();for(int y=points.Min(p=>p.Y)+24;y<points.Max(p=>p.Y);y+=16)for(int x=points.Min(p=>p.X)+24;x<points.Max(p=>p.X);x+=16){Point p=new Point(x,y);if(ClearSpot(p,s))return p;}}throw new InvalidDataException("The first sector needs enough space for the player start. Make it at least 64 units across.");}
        bool ClearSpot(Point point,int sector){return GeometryTools.SectorAt(map,point)==sector&&GeometryTools.Boundary(map,sector).All(i=>{Wall w=map.Walls[i];return CodeImp.DoomBuilder.Geometry.Line2D.GetDistanceToLineSq(map.Vertices[w.Start].Vec,map.Vertices[w.End].Vec,point.Vec,true)>=24*24;});}
        void NewMap(){NeedRom();using(var dialog=new NewMapDialog(map.Name))if(dialog.ShowDialog(this)==DialogResult.OK){int index=rom.Project.Maps.IndexOf(map);Map fresh=dialog.Choice==0?MapTemplates.Blank(rom,map.Slot):dialog.Choice==1?MapTemplates.Starter(rom,map.Slot):dialog.Choice==2?MapTemplates.Door(rom,map.Slot):MapTemplates.Lift(rom,map.Slot);rom.Project.Maps[index]=fresh;map=fresh;Commit();RefreshMaps(fresh.Slot,"");canvas.Fit();scene.ResetCamera();if(dialog.Choice==0)StartDraw();else SelectMode("Sectors");Status("New map ready. D draws sectors/lines; F3 opens 3D; F5 checks the native build.");}}
        void AddObject(Point point){Guard(delegate{Edit(delegate{map.Things.Add(new Thing{Type=map.Things.Any(t=>t.Type==0)?15:0,Flags=map.Things.Any(t=>t.Type==0)?0x87:0xef,X=point.X,Y=point.Y});});RefreshItems(map.Things.Count-1);});}
        void DeleteSelection(){NeedRom();int index=items.SelectedIndex;if(index<0)return;Edit(delegate{if(mode=="Objects"){Bin.Require(map.Things[index].Type!=0,"Move the player start instead of deleting it.");map.Things.RemoveAt(index);}else if(mode=="Walls"){EnableCurrent();map.Walls.RemoveAt(index);Status("Line deleted. Repair any open sector boundary before building.");}else if(mode=="Vertices"){EnableCurrent();Bin.Require(!map.Walls.Any(w=>w.Start==index||w.End==index),"Delete adjoining linedefs before deleting this vertex.");map.Vertices.RemoveAt(index);foreach(Wall w in map.Walls){if(w.Start>index)w.Start--;if(w.End>index)w.End--;}}else throw new InvalidDataException("Select a thing, linedef or unused vertex to delete. Use Undo to remove a newly drawn sector.");});}
        void FlipLine(){NeedRom();Bin.Require(mode=="Walls"&&items.SelectedIndex>=0,"Select a two-sided linedef first.");Edit(delegate{EnableCurrent();Wall w=map.Walls[items.SelectedIndex];Bin.Require(w.BackFace>=0,"Only two-sided linedefs can be flipped without opening a sector.");GeometryTools.Reverse(map,w);});}
        int SelectedSector(){if(mode=="Sectors"&&items.SelectedIndex>=0)return items.SelectedIndex;if(mode=="Walls"&&items.SelectedIndex>=0)return GeometryTools.Near(map,map.Walls[items.SelectedIndex]);if(mode=="Objects"&&items.SelectedIndex>=0){Thing t=map.Things[items.SelectedIndex];return GeometryTools.SectorAt(map,new Point(t.X,t.Y));}return 0;}
        void Preset(SectorMotion motion){NeedRom();int sector=SelectedSector();Bin.Require(sector>=0&&sector<map.Sectors.Count,"Draw/select a sector first.");Edit(delegate{EnableCurrent();GeometryTools.Preset(map,sector,motion);});SelectMode("Sectors");items.SelectedIndex=sector;Status("Preset applied. Check the linked linedef action and target tag; F5 validates the native build.");}
        void Toggle3D(){NeedRom();if(!scene.Visible){Bin.Require(map.Sectors.Count>0&&map.Walls.Count>=3,"Draw a closed sector before entering 3D.");canvas.CancelOutline();canvas.Drawing=false;scene.Map=map;scene.Visible=true;canvas.Visible=false;scene.BringToFront();scene.ResetCamera();scene.Focus();}else{scene.Visible=false;canvas.Visible=true;canvas.BringToFront();canvas.Focus();}UpdateButtons();}
        void Pick3D(ScenePick pick){if(pick.Sector<0)return;lastPick=pick;if(pick.Surface=="Floor"||pick.Surface=="Ceiling"){SelectMode("Sectors");items.SelectedIndex=pick.Sector;}else{SelectMode("Walls");if(pick.Wall>=0&&pick.Wall<items.Items.Count)items.SelectedIndex=pick.Wall;}Status("3D surface selected: "+pick.Surface+". Edit properties or browse surface assets.");}
        void ChooseAsset(){NeedRom();int index=items.SelectedIndex;Bin.Require(index>=0,"Select a wall, surface or sector first.");bool flat=mode=="Sectors";Bin.Require(flat||mode=="Walls"||mode=="Surfaces","Select a wall, surface or sector first.");string field=properties.SelectedGridItem!=null&&properties.SelectedGridItem.PropertyDescriptor!=null?properties.SelectedGridItem.PropertyDescriptor.Name:"";
            bool ceiling=field=="CeilingTexture"||(scene.Visible&&lastPick!=null&&lastPick.Surface=="Ceiling"),lower=field=="Lower"||field=="FrontLower"||field=="BackLower"||(scene.Visible&&lastPick!=null&&lastPick.Surface=="Lower wall"),back=field=="BackTexture"||field=="BackLower";
            Wall line=mode=="Walls"?map.Walls[index]:null;if(line!=null&&scene.Visible&&lastPick!=null&&lastPick.Wall==index)back=lastPick.Face==line.BackFace;
            Face face=mode=="Surfaces"?map.Faces[index]:line==null?null:back?GeometryTools.Back(map,line):GeometryTools.Front(map,line);Bin.Require(flat||face!=null,"This line has no surface on that side.");int current=flat?(ceiling?map.Sectors[index].CeilingTexture:map.Sectors[index].FloorTexture):lower?face.Lower:face.Upper;
            using(var dialog=new AssetDialog(rom,!flat,ceiling,current))if(dialog.ShowDialog(this)==DialogResult.OK){Edit(delegate{int[] targets=(mode=="Walls"||flat)&&canvas.Selection.Count>0?canvas.Selection.ToArray():new[]{index};if(line!=null)EnableCurrent();foreach(int target in targets){if(flat){if(ceiling)map.Sectors[target].CeilingTexture=dialog.Value;else map.Sectors[target].FloorTexture=dialog.Value;}else{Face selectedFace=line==null?map.Faces[target]:back?GeometryTools.Back(map,map.Walls[target]):GeometryTools.Front(map,map.Walls[target]);Bin.Require(selectedFace!=null,"A selected line has no surface on that side.");if(lower)selectedFace.Lower=dialog.Value;else selectedFace.Upper=dialog.Value;}}});}
        }
        void CheckMap(){NeedRom();byte[] image=rom.Compile();string result="Native map check passed.";if(map.EditGeometry){NativeBuildInfo info=NativeCompiler.Build(rom,image,map);result+="\n\n"+info.Vertices+" vertices, "+info.Lines+" linedefs, "+info.Segments+" segments\n"+info.Areas+" subsectors, "+info.Nodes+" BSP nodes\nGeometry: "+info.GeometryBytes+" / "+info.GeometryCapacity+" bytes\nObjects/collision/platforms: "+info.DataBytes+" / "+info.DataCapacity+" bytes\n"+info.Doors+" doors, "+info.Lifts+" lift groups, "+info.Floors+" floor groups, "+info.Stairs+" stair groups, "+info.Ceilings+" ceiling groups";}Status("Map check passed. Ready to apply.");MessageBox.Show(this,result,"DoomSNESed - map check",MessageBoxButtons.OK,MessageBoxIcon.Information);}
        void RestoreMap(){NeedRom();if(MessageBox.Show(this,"Restore "+map.Name+" from your original ROM?","Restore map",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;int slot=map.Slot;rom.Project.Maps[rom.Project.Maps.IndexOf(map)]=rom.Read(slot);map=rom.Project.Maps.First(m=>m.Slot==slot);Commit();RefreshMaps(slot,"");}
        void SaveProject(bool saveAs){NeedRom();if(projectPath==null||saveAs)using(var dialog=new SaveFileDialog{Filter="DoomSNESed project|*.sned",FileName="My SNES levels.sned"}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;projectPath=dialog.FileName;}rom.SaveProject(projectPath);dirty=false;Text="DoomSNESed - "+map.Name;Status("Project saved: "+projectPath);}
        void OpenProject(){NeedRom();if(!CanDiscard())return;using(var dialog=new OpenFileDialog{Filter="DoomSNESed project|*.sned"})if(dialog.ShowDialog(this)==DialogResult.OK){rom.LoadProject(dialog.FileName);projectPath=dialog.FileName;dirty=false;undo.Clear();redo.Clear();lastSnapshot=Snapshot();RefreshMaps(rom.Project.CampaignSlots==null?0:rom.Project.CampaignSlots[0],"");Status("Project opened. Draw, edit or enter the 3D view.");}}
        void ExportPatch(){NeedRom();byte[] image=rom.Compile();using(var dialog=new SaveFileDialog{Filter="DoomSNESed level patch|*.dse",FileName="My SNES levels.dse"})if(dialog.ShowDialog(this)==DialogResult.OK){rom.SavePatch(dialog.FileName,image);Status("Level patch exported.");}}
        void ExportRom(){NeedRom();byte[] image=rom.Compile();using(var dialog=new SaveFileDialog{Filter="SNES ROM copy|*.sfc",FileName="DoomSNESed-custom.sfc"})if(dialog.ShowDialog(this)==DialogResult.OK){Bin.Require(!string.Equals(Path.GetFullPath(dialog.FileName),rom.PathName,StringComparison.OrdinalIgnoreCase),"Choose a different file. The source ROM is protected.");Bin.W16(image,0x7fdc,0xffff);Bin.W16(image,0x7fde,0);int checksum=0;foreach(byte b in image)checksum=(checksum+b)&65535;Bin.W16(image,0x7fde,checksum);Bin.W16(image,0x7fdc,checksum^65535);Bin.Atomic(dialog.FileName,image);Status("Patched ROM copy exported for an external emulator.");}}
        void Apply(){NeedRom();Bin.Require(!RomLayout.SourceBuilt(rom.Bytes),"Use Export ROM for this DoomFX source layout. The relocated engine is not supported by native recompiler patches.");byte[] image=rom.Compile();rom.SaveProject(Path.Combine(patchRoot,"active.sned"));rom.SavePatch(Path.Combine(patchRoot,"active.dse"),image);dirty=false;Text="DoomSNESed - "+map.Name;Status("Applied and saved. Restart DoomSNESRecomp to play these levels. Your original ROM is unchanged.");banner.Detail="Levels applied - restart the game to play";banner.Invalidate();}
        void ClearPatch(){string path=Path.Combine(patchRoot,"active.dse");if(File.Exists(path))File.Delete(path);Status("Original levels selected for the next launch. Your project remains open.");}
        void Help(){MessageBox.Show(this,"DRAW\nNew map > Empty map. Press D, click outline points, then close the outline or press Enter. Adjacent edges become portals. Two boundary points + Enter split a sector. Esc cancels the draft.\n\nEDIT\n1 Things, 2 Vertices, 3 Linedefs, 4 Sectors, 5 Surfaces. Arrow keys pan in 2D. Ctrl+click selects multiple lines/sectors; right-click opens properties. Drag vertices/things; use properties for heights, floor types, native actions and tags. Browse surface assets shows ROM thumbnails. Sector presets include doors, lifts, stairs and crushers.\n\n3D\nF3 toggles the textured view. WASD move, right drag/arrows look, Q/E fly. Click to select the aimed surface. Ctrl+wheel changes its floor; Shift+wheel changes its ceiling. View > Preview doors open helps inspect rooms beyond closed doors. This is an editing preview, not the running game.\n\nBUILD\nF5 checks BSP, collision, platform tables and ROM space. F6 applies a saved patch for the next launch. Restart the game to play it. Larger maps may exceed their slot's native ROM allocation.\n\nSource ROM and other saved projects remain unchanged.","DoomSNESed - quick guide");}
        public void PrepareSmoke(string view){if(view=="3d"){int slot=map.Slot;rom.Project.Maps[rom.Project.Maps.IndexOf(map)]=MapTemplates.Door(rom,slot);RefreshMaps(slot,"");scene.OpenDoors=true;Toggle3D();}else SelectMode("Sectors");dirty=false;}
        protected override bool ProcessCmdKey(ref Message msg,Keys keyData){if(keyData==(Keys.Control|Keys.Z)||keyData==(Keys.Control|Keys.Y)){if(((long)msg.LParam&0x40000000L)==0)Guard(delegate{History(keyData==(Keys.Control|Keys.Y));});return true;}if(!scene.Visible&&canvas.Focused&&(keyData&Keys.Modifiers)==0){string selected=keyData==Keys.D1?"Objects":keyData==Keys.D2?"Vertices":keyData==Keys.D3?"Walls":keyData==Keys.D4?"Sectors":keyData==Keys.D5?"Surfaces":null;if(selected!=null){SelectMode(selected);return true;}if(keyData==Keys.D){Guard(StartDraw);return true;}}return base.ProcessCmdKey(ref msg,keyData);}
        protected override void Dispose(bool disposing){if(disposing){preview.Dispose();scene.Dispose();if(Icon!=null)Icon.Dispose();}base.Dispose(disposing);}
    }
}


